import java.util.*;

public class Main {

  public static void main(String[] args) throws Exception {
    // Exercise 1: Print a first result
    String message = "Hello, Java";
    System.out.println(message);
    assert message.equals("Hello, Java");

// Exercise 2: Evaluate before printing
int total = 2 + 3;
String line = "total=" + total;
assert total == 5;
assert line.equals("total=5");

// Exercise 3: Trace sequential state
int count = 1;
count = count + 1;
count = count * 3;
assert count == 6;

// Exercise 4: Verify assertion mode
boolean enabled = false;
assert enabled = true;
if (!enabled) throw new IllegalStateException("Run with -ea");
assert enabled;

// Exercise 5: Separate runtime failure
boolean dividedByZero = false;
try {
  int zero = 0;
  int ignored = 10 / zero;
} catch (ArithmeticException expected) {
  dividedByZero = true;
}
assert dividedByZero;

// Exercise 6: Observe a real compiler diagnostic
var compiler = javax.tools.ToolProvider.getSystemJavaCompiler();
assert compiler != null : "A JDK compiler is required";
var diagnostics = new javax.tools.DiagnosticCollector<javax.tools.JavaFileObject>();
var source = new javax.tools.SimpleJavaFileObject(
  java.net.URI.create("string:///Broken.java"),
  javax.tools.JavaFileObject.Kind.SOURCE
) {
  public CharSequence getCharContent(boolean ignore) {
    return "class Broken { int f() { return 1 } }";
  }
};

    try (var files = compiler.getStandardFileManager(diagnostics, null, null)) {
      boolean compiled = compiler
        .getTask(
          null,
          files,
          diagnostics,
          List.of("-proc:none", "--release", "21"),
          null,
          List.of(source)
        )
        .call();
      assert !compiled;
      assert diagnostics
        .getDiagnostics()
        .stream()
        .anyMatch(d -> d.getKind() == javax.tools.Diagnostic.Kind.ERROR);
    }
  }
}

import java.util.*;

public class Main {

  public static void main(String[] args) throws Exception {
    // Exercise 1: Filter and sum
    int total = List.of(1, 2, 3, 4)
      .stream()
      .filter(value -> value % 2 == 0)
      .mapToInt(value -> value * value)
      .sum();
    assert total == 20;

// Exercise 2: Observe laziness with an explicit terminal
var calls = new java.util.concurrent.atomic.AtomicInteger();
var pipeline = List.of(1, 2, 3)
  .stream()
  .map(value -> {
    calls.incrementAndGet();
    return value * 2;
  });
assert calls.get() == 0;
assert pipeline.toList().equals(List.of(2, 4, 6)) && calls.get() == 3;

// Exercise 3: Group with a collector
Map<String, Long> counts = List.of("red", "blue", "red")
  .stream()
  .collect(
    java.util.stream.Collectors.groupingBy(
      value -> value,
      java.util.stream.Collectors.counting()
    )
  );
assert counts.equals(Map.of("red", 2L, "blue", 1L));

// Exercise 4: Reject stream reuse
var once = List.of(1, 2).stream();
long counted = once.count();
assert counted == 2;
boolean reused = false;
try {
  once.toList();
} catch (IllegalStateException expected) {
  reused = true;
}
assert reused;

    // Exercise 5: Check the reduction identity
    int correct = List.of(1, 2, 3).stream().reduce(0, Integer::sum);
    int wrong = List.of(1, 2, 3).stream().reduce(10, Integer::sum);
    assert correct == 6 && wrong == 16;

    // Exercise 6: Expose nonassociative subtraction
    assert (10 - 3) - 2 == 5 && 10 - (3 - 2) == 9;
    assert java.util.stream.IntStream.rangeClosed(1, 100).parallel().sum() == 5050;
    System.out.println("java-014: all six exercises passed");
  }
}

import java.util.*;

public class Main {

  interface Catalog {
    java.util.OptionalLong unitPrice(String id) throws java.io.IOException;
  }

  record Quote(String item, int quantity, long totalCents, java.time.Instant created) {}

  static long total(int quantity, long unitPrice) {
    if (quantity <= 0 || unitPrice < 0) throw new IllegalArgumentException(
      "positive quantity and nonnegative price required"
    );
    return Math.multiplyExact((long) quantity, unitPrice);
  }

record Service(
  Catalog catalog,
  java.util.function.Supplier<java.time.Instant> clock,
  java.util.function.Consumer<String> audit
) {
  Service {
    Objects.requireNonNull(catalog);
    Objects.requireNonNull(clock);
    Objects.requireNonNull(audit);
  }

  Quote quote(String id, int quantity) throws java.io.IOException {
    if (id == null || id.isBlank() || quantity <= 0) throw new IllegalArgumentException(
      "valid item and quantity required"
    );
    long price = catalog
      .unitPrice(id)
      .orElseThrow(() -> new NoSuchElementException("unknown item"));
    long amount = total(quantity, price);
    Quote result = new Quote(id, quantity, amount, clock.get());
    audit.accept("quoted:" + id);
    return result;
  }
}

public static void main(String[] args) throws Exception {
  // Exercise 1: Test the pure calculation
  assert total(3, 125) == 375;
  boolean invalid = false;
  try {
    total(0, 125);
  } catch (IllegalArgumentException expected) {
    invalid = true;
  }
  assert invalid;

  // Exercise 2: Compose a deterministic service
  List<String> audit = new ArrayList<>();
  var instant = java.time.Instant.parse("2026-01-01T00:00:00Z");
  Catalog catalog = id ->
    id.equals("item-a") ? java.util.OptionalLong.of(125) : java.util.OptionalLong.empty();
  Service service = new Service(catalog, () -> instant, audit::add);
  Quote quote = service.quote("item-a", 2);
  assert quote.totalCents() == 250 &&
  quote.created().equals(instant) &&
  audit.equals(List.of("quoted:item-a"));

  // Exercise 3: Reject an unknown catalog item
  boolean missing = false;
  try {
    service.quote("missing", 2);
  } catch (NoSuchElementException expected) {
    missing = true;
  }
  assert missing && audit.size() == 1;

// Exercise 4: Propagate an infrastructure failure
List<String> failures = new ArrayList<>();
Service unavailable = new Service(
  id -> {
    throw new java.io.IOException("catalog unavailable");
  },
  () -> instant,
  failures::add
);
boolean propagated = false;
try {
  unavailable.quote("item-a", 1);
} catch (java.io.IOException expected) {
  propagated = expected.getMessage().equals("catalog unavailable");
}
assert propagated && failures.isEmpty();

// Exercise 5: Prove invalid quantity fails before a repository call
var calls = new java.util.concurrent.atomic.AtomicInteger();
Service checked = new Service(
  id -> {
    calls.incrementAndGet();
    return java.util.OptionalLong.of(1);
  },
  () -> instant,
  value -> {}
);
boolean rejected = false;
try {
  checked.quote("item-a", -1);
} catch (IllegalArgumentException expected) {
  rejected = true;
}
assert rejected && calls.get() == 0;

    // Exercise 6: Detect arithmetic overflow without an event
    List<String> overflowAudit = new ArrayList<>();
    Service expensive = new Service(
      id -> java.util.OptionalLong.of(Long.MAX_VALUE),
      () -> instant,
      overflowAudit::add
    );
    boolean overflow = false;
    try {
      expensive.quote("x", 2);
    } catch (ArithmeticException expected) {
      overflow = true;
    }
    assert overflow && overflowAudit.isEmpty();
    System.out.println("java-034: all six exercises passed");
  }
}
